with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ITEM_CODE
        , UW_LOAD_FLAG as ITEM_APPLIED_INDICATOR
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'BRJ_LOADING' as ITEM_CODE
        , BRJ_LOAD_YN as ITEM_APPLIED_INDICATOR
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'COMMERCIAL_DISC' as ITEM_CODE
        , CM_DISC_FLAG as ITEM_APPLIED_INDICATOR
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        ITEM_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ITEM_APPLIED_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ITEM_APPLIED_INDICATOR end)) as ITEM_APPLIED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, ITEM_CODE
),

hashed as (
    select
        *,
        case when ITEM_CODE is not null or ITEM_APPLIED_INDICATOR is not null
                     then md5(upper(coalesce(cast(ITEM_CODE as varchar), '') || '|' || coalesce(cast(ITEM_APPLIED_INDICATOR as varchar), '')))
                end as SAT_POLICY_DISCOUNT_LOADING_APPLIED_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_DISCOUNT_LOADING_APPLIED_HASHDIFF is not null
